WITH valid AS (SELECT id, carrier, shipped_date, delivered_date, cost, status, CASE WHEN cost >= 107 THEN 'High' WHEN cost >= 43 THEN 'Medium' ELSE 'Low' END AS cost_band, ADD_MONTHS(delivered_date, 3) AS delivered_date_plus_months, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM shipments WHERE shipped_date > DATE '2023-08-13' AND order_id IS NOT NULL) SELECT id, carrier, status, cost_band, delivered_date_plus_months, resolved_carrier, LAG(cost) OVER (PARTITION BY status ORDER BY delivered_date_plus_months, id) AS prev_cost, LEAD(cost) OVER (PARTITION BY status ORDER BY delivered_date_plus_months, id) AS next_cost, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date_plus_months, id) AS event_seq, SUM(cost) OVER (ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost FROM valid;
